export type OidcCallbackData = {
    body?: never;
    path?: never;
    query?: {
        /**
         * The authorization code, on success.
         */
        code?: string;
        /**
         * The state this instance generated, echoed back.
         */
        state?: string;
        /**
         * The provider's error code, when it refused.
         */
        error?: string;
        /**
         * The provider's human-readable reason, when it refused.
         */
        error_description?: string;
    };
    url: '/api/v1/auth/oidc/callback';
};

export type OidcCallbackErrors = {
    /**
     * The provider refused, the state did not match, the ID token did not validate, or a link was finished after its session was signed out. One message for every way the protocol can fail.
     */
    401: ProblemDetail;
    /**
     * The identity names a disabled account, or a new account would pass `auth.max_users`.
     */
    403: ProblemDetail;
    /**
     * No provider is configured on this instance.
     */
    404: ProblemDetail;
    /**
     * The sign-in was started to link an identity and could not be: it was finished on another account's session, the identity belongs to another account (which is never named), or this account already holds one at that provider. Nothing was linked and no account was created.
     */
    409: ProblemDetail;
    /**
     * The provider could not be reached for the token exchange.
     */
    502: ProblemDetail;
};

export type OidcCallbackError = OidcCallbackErrors[keyof OidcCallbackErrors];

export type OidcLoginData = {
    body?: never;
    path?: never;
    query?: {
        /**
         * Recognized so that a request meaning to link is told where linking
         * lives, rather than quietly started as an ordinary sign-in. Starting a
         * link is `POST /auth/oidc/login`; see [`start_link`] for why it cannot
         * be a GET.
         */
        link?: boolean;
        /**
         * Where to send the browser once the sign-in completes: a path on this
         * instance, which the callback 302s to instead of the root of the base
         * path.
         *
         * The OAuth consent page is what this exists for. A client sends a
         * browser to `/authorize?request=<id>`, Fluid finds nobody signed in and
         * carries the intended location to the login page, and a provider sign-in
         * has to come back to that exact request: the pending authorization is
         * only reachable by its id, so landing anywhere else loses it.
         *
         * Anything [`safe_return_path`] does not accept is dropped rather than
         * refused, and the sign-in lands on the root of the base path (`/` at the
         * root): the person did sign in, and only the destination was unusable.
         */
        return_to?: string;
    };
    url: '/api/v1/auth/oidc/login';
};

export type OidcLoginErrors = {
    /**
     * `link=true`, which is the POST's job; or a request with no Host header, or one that is not a bare host and port, so no redirect uri can be derived.
     */
    400: ProblemDetail;
    /**
     * No provider is configured on this instance.
     */
    404: ProblemDetail;
    /**
     * The provider's discovery document could not be fetched, or it names a tenant-independent issuer.
     */
    502: ProblemDetail;
    /**
     * Too many sign-ins are in flight to start another. Wait a moment and try again.
     */
    503: ProblemDetail;
};

export type OidcLoginError = OidcLoginErrors[keyof OidcLoginErrors];

