export type SetupData = {
    body: SetupBody;
    path?: never;
    query?: never;
    url: '/api/v1/auth/setup';
};

export type SetupErrors = {
    /**
     * The body is not JSON.
     */
    400: ProblemDetail;
    /**
     * The request did not come from the machine that serves this instance and carried no setup token, or the wrong one; one message covers both, so nothing says whether a token was close. When this instance holds a token, the problem document carries the extension member `token_required: true`, which is what a client keys a token field on - an instance that has no token to enter refuses without the member, so no dead-end input is ever offered.
     */
    403: ProblemDetail;
    /**
     * An account already exists, so the first-run slot is permanently gone. Checked before locality and before the token, and answered for a lost race too. 410 rather than 403 because a credential cannot change the answer, and rather than 409 because the conflict never resolves.
     */
    410: ProblemDetail;
    /**
     * The body is not `application/json`. Load bearing rather than pedantic: with no CORS layer on this surface, it is what stops another origin from driving this pre-session POST with a form.
     */
    415: ProblemDetail;
    /**
     * The body is JSON but not a setup, the password is empty, or the name is not one this store can key on.
     */
    422: ProblemDetail;
};

export type SetupError = SetupErrors[keyof SetupErrors];

export type SetupResponses = {
    /**
     * The first admin was created and signed in. The session cookie is set and the CSRF token is in the body, exactly as `POST /auth/login` answers.
     */
    200: LoginResponse;
};

export type SetupResponse = SetupResponses[keyof SetupResponses];

